from typing import Dict

def fib(n: int) -> int:
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    if n <= 0:
        return "Input should be a positive integer."
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        fib_dict: Dict[int, int] = {1: 1, 2: 1}
        for i in range(3, n + 1):
            fib_dict[i] = fib_dict[i - 1] + fib_dict[i - 2]
        return fib_dict[n]
```

