from math import sqrt

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    # Check if the number is less than 100
    if a < 100:
        # Check if the number is divisible by 2, 3, or 5
        if a % 2 == 0 or a % 3 == 0 or a % 5 == 0:
            return False

        # Check if the number is a prime number
        if a > 2:
            for i in range(2, int(sqrt(a)) + 1):
                if a % i == 0:
                    return False

        # Check if the number is the multiplication of 3 prime numbers
        for i in range(2, int(sqrt(a)) + 1):
            for j in range(i, int(sqrt(a)) + 1):
                for k in range(j, int(sqrt(a)) + 1):
                    if i * j * k == a and is_prime(i) and is_prime(j) and is_prime(k):
                        return True

        # If no 3 prime numbers are found, return False
        return False

    # If the number is not less than 100, return False
    return False

def is_prime(n):
    """Check if a number is prime"""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(sqrt(n))
    for d in range(3, 1 + max_divisor, 2):
        if n % d == 0:
            return False
    return True
