        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    factors = set()
    for i in range(2, int(math.sqrt(a)) + 1):
        while a % i == 0:
            factors.add(i)
