from functools import lru_cache

def fib(n: int):
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    @lru_cache(maxsize=None)
    def fib_helper(k: int) -> int:
        if k <= 1:
            return k
        return fib_helper(k - 1) + fib_helper(k - 2)
    return fib_helper(n)
